/* ====================================================
   DM GROUP KSA - PRODUCTION COMMAND CENTER
   CSS-ONLY ERPNext Custom HTML Block Preview
   ==================================================== */

.pcc {
  --navy: #172f50;
  --blue: #2563eb;
  --teal: #0d9488;
  --purple: #8064d8;
  --amber: #d69a30;
  --ink: #182d49;
  --muted: #718198;
  --border: #e3e9f2;
  --surface: #f4f7fb;
  width: 100%;
  font: 13px/1.5 Inter, Arial, sans-serif;
  color: var(--ink);
}

.pcc * {
  box-sizing: border-box;
}

.pcc > .pcc-toggle {
  position: absolute !important;
  opacity: 0 !important;
  width: 0 !important;
  height: 0 !important;
  pointer-events: none;
}

/* ====================================================
   LANGUAGE SWITCH
   ==================================================== */

.pcc .ar {
  display: none;
}

#pcc-ar:checked ~ .pcc-shell .en {
  display: none !important;
}

#pcc-ar:checked ~ .pcc-shell .ar {
  display: inline;
}

#pcc-ar:checked ~ .pcc-shell {
  direction: rtl;
  text-align: right;
}

#pcc-en:checked ~ .pcc-shell .pcc-language label[for="pcc-en"],
#pcc-ar:checked ~ .pcc-shell .pcc-language label[for="pcc-ar"] {
  color: #154273;
  background: #fff;
}

.pcc-shell {
  border: 1px solid var(--border);
  border-radius: 14px;
  overflow: hidden;
  background: var(--surface);
}

/* ====================================================
   HEADER
   ==================================================== */

.pcc-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 20px;
  flex-wrap: wrap;
  padding: 25px 28px;
  color: #fff;
  background: linear-gradient(115deg, #112b4b, #245887);
}

.pcc-eyebrow {
  font-size: 10px;
  letter-spacing: 1.4px;
  font-weight: 800;
  color: #c3d9f4;
}

.pcc-header h2 {
  margin: 7px 0 5px;
  font-size: 25px;
  font-weight: 800;
  line-height: 1.3;
  color: #fff;
}

.pcc-header p {
  margin: 0;
  color: #d8e7f8;
  font-size: 12px;
}

.pcc-head-actions {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 10px;
}

.pcc-preview {
  display: inline-block;
  padding: 5px 11px;
  border-radius: 20px;
  border: 1px solid #80a8d4;
  font-size: 10px;
  letter-spacing: .5px;
  color: #e2efff;
  font-weight: 800;
}

.pcc-language {
  display: flex;
  padding: 4px;
  border: 1px solid #6d91b9;
  border-radius: 9px;
  background: rgba(255,255,255,.1);
  gap: 4px;
}

.pcc-language label {
  margin: 0;
  cursor: pointer;
  padding: 8px 15px;
  font-size: 12px;
  font-weight: 750;
  color: #e2efff;
  border-radius: 6px;
  user-select: none;
}

/* ====================================================
   FILTER BAR
   ==================================================== */

.pcc-filterbar {
  display: grid;
  grid-template-columns: 1.2fr 1.2fr 1fr 1fr auto;
  gap: 12px;
  align-items: end;
  padding: 16px 20px;
  background: #fff;
  border-bottom: 1px solid var(--border);
}

.pcc-filterbar label {
  display: flex;
  flex-direction: column;
  gap: 5px;
  min-width: 0;
  font-size: 11px;
  font-weight: 700;
  color: #64758d;
}

.pcc-filterbar select,
.pcc-filterbar input {
  width: 100%;
  min-width: 0;
  height: 37px;
  padding: 7px 9px;
  border: 1px solid #d9e2ef;
  border-radius: 7px;
  background: #fff;
  color: var(--ink);
  font-size: 12px;
}

.pcc-filter-info {
  white-space: nowrap;
  padding: 10px;
  border-radius: 7px;
  background: #fff5dd;
  border: 1px solid #f8e7bb;
  color: #956514;
  font-size: 10px;
}

/* ====================================================
   TAB NAVIGATION
   ==================================================== */

.pcc-nav {
  display: flex;
  gap: 5px;
  flex-wrap: wrap;
  padding: 12px 14px;
  border-bottom: 1px solid var(--border);
  background: #fff;
}

.pcc-nav label {
  margin: 0;
  padding: 9px 12px;
  border-radius: 7px;
  border: 1px solid transparent;
  font-size: 11px;
  font-weight: 750;
  color: #5d6f87;
  cursor: pointer;
  user-select: none;
  transition: background .15s ease;
}

.pcc-nav label:hover {
  background: #f0f5fc;
  color: #1853a7;
}

#pcc-overview:checked ~ .pcc-shell label[for="pcc-overview"],
#pcc-output:checked ~ .pcc-shell label[for="pcc-output"],
#pcc-workorders:checked ~ .pcc-shell label[for="pcc-workorders"],
#pcc-jobs:checked ~ .pcc-shell label[for="pcc-jobs"],
#pcc-cost:checked ~ .pcc-shell label[for="pcc-cost"],
#pcc-materials:checked ~ .pcc-shell label[for="pcc-materials"],
#pcc-workforce:checked ~ .pcc-shell label[for="pcc-workforce"],
#pcc-planning:checked ~ .pcc-shell label[for="pcc-planning"],
#pcc-quality:checked ~ .pcc-shell label[for="pcc-quality"] {
  background: #e9f2ff;
  color: #1852ab;
  border-color: #cddff8;
}

/* ====================================================
   PAGE VISIBILITY
   ==================================================== */

.pcc-page {
  display: none;
}

#pcc-overview:checked ~ .pcc-shell .pcc-page-overview,
#pcc-output:checked ~ .pcc-shell .pcc-page-output,
#pcc-workorders:checked ~ .pcc-shell .pcc-page-workorders,
#pcc-jobs:checked ~ .pcc-shell .pcc-page-jobs,
#pcc-cost:checked ~ .pcc-shell .pcc-page-cost,
#pcc-materials:checked ~ .pcc-shell .pcc-page-materials,
#pcc-workforce:checked ~ .pcc-shell .pcc-page-workforce,
#pcc-planning:checked ~ .pcc-shell .pcc-page-planning,
#pcc-quality:checked ~ .pcc-shell .pcc-page-quality {
  display: block;
}

/* ====================================================
   MAIN LAYOUT
   ==================================================== */

.pcc-main {
  padding: 20px;
  min-height: 500px;
}

.pcc-notice {
  background: #eaf2ff;
  border: 1px solid #d2e3fa;
  border-radius: 9px;
  padding: 12px 15px;
  color: #3c628b;
  font-size: 11px;
  margin-bottom: 20px;
}

.pcc-section-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  margin: 0 0 18px;
}

.pcc-kicker {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 1.1px;
  color: #3671b9;
}

.pcc-section-head h3 {
  font-size: 20px;
  font-weight: 800;
  color: var(--ink);
  margin: 4px 0;
}

.pcc-section-head p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.pcc-chip {
  display: inline-block;
  padding: 6px 11px;
  font-size: 10px;
  font-weight: 750;
  color: #65768d;
  border: 1px solid var(--border);
  background: #fff;
  border-radius: 20px;
}

.pcc-link {
  display: inline-block;
  padding: 8px 12px;
  border-radius: 7px;
  background: #eaf2ff;
  color: #1955ad !important;
  font-size: 11px;
  font-weight: 750;
  text-decoration: none !important;
}

/* ====================================================
   KPI CARDS AND EXPANDABLE DETAILS
   ==================================================== */

.pcc-kpis {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  align-items: start;
  gap: 13px;
  margin-bottom: 18px;
}

.pcc-kpi,
.pcc-panel {
  background: #fff;
  border: 1px solid var(--border);
  border-radius: 11px;
  box-shadow: 0 2px 8px rgba(25,50,80,.04);
  min-width: 0;
}

.pcc-kpi {
  overflow: hidden;
}

.pcc-kpi[open] {
  border-color: #7cb2ef;
  box-shadow: 0 4px 13px rgba(38,99,235,.09);
}

.pcc-kpi summary {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  min-height: 155px;
  padding: 17px;
  cursor: pointer;
  list-style: none;
}

.pcc-kpi summary::-webkit-details-marker {
  display: none;
}

.pcc-kpi summary::marker {
  content: "";
}

.pcc-kpi-label {
  min-height: 32px;
  color: #637791;
  font-size: 11px;
  font-weight: 750;
}

.pcc-kpi strong {
  display: block;
  color: #1b3556;
  font-size: 27px;
  font-weight: 850;
  margin: 7px 0 4px;
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}

.pcc-kpi .pcc-warning-value {
  font-size: 20px;
  color: #a86f17;
}

.pcc-kpi small {
  font-size: 10px;
  color: #8594a7;
  line-height: 1.5;
}

.pcc-more {
  display: block;
  color: #2365c1;
  font-size: 10px;
  font-weight: 750;
  padding-top: 12px;
  margin-top: auto;
}

.pcc-kpi[open] .pcc-more {
  color: #0e9278;
}

.pcc-detail {
  border-top: 1px solid #e7edf6;
  background: #f9fbfe;
  padding: 13px;
  font-size: 11px;
}

.pcc-detail > div {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  border-bottom: 1px solid #e8eef6;
  padding: 8px 0;
  color: #62768d;
}

.pcc-detail b {
  color: #203b59;
  font-variant-numeric: tabular-nums;
}

.pcc-detail p {
  color: #62768d;
  font-size: 11px;
  line-height: 1.65;
  margin: 4px 0 12px;
}

.pcc-detail a {
  display: block;
  background: #2563eb;
  color: #fff !important;
  text-align: center;
  padding: 9px 12px;
  border-radius: 7px;
  font-size: 11px;
  font-weight: 750;
  text-decoration: none !important;
  margin-top: 11px;
}

.pcc-detail a:hover {
  background: #194ca8;
}

/* ====================================================
   PANELS
   ==================================================== */

.pcc-grid2 {
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  gap: 15px;
  margin-bottom: 17px;
}

.pcc-panel {
  padding: 18px;
  margin-bottom: 17px;
}

.pcc-grid2 .pcc-panel {
  margin-bottom: 0;
}

.pcc-panel-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 17px;
}

.pcc-panel-head h4 {
  margin: 0;
  color: #263c58;
  font-size: 14px;
  font-weight: 800;
}

.pcc-panel-head > span {
  color: #8798ad;
  font-size: 10px;
}

.pcc-panel-head a {
  color: #2461b8;
  font-size: 11px;
  font-weight: 750;
  text-decoration: none;
}

.pcc-note {
  color: #8897a9;
  font-size: 10px;
  line-height: 1.6;
  margin: 13px 0 0;
}

/* ====================================================
   DONUT CHART
   ==================================================== */

.pcc-donut-wrap {
  display: flex;
  justify-content: center;
  align-items: center;
  flex-wrap: wrap;
  gap: 25px;
}

.pcc-donut {
  display: flex;
  justify-content: center;
  align-items: center;
  flex: 0 0 166px;
  width: 166px;
  height: 166px;
  border-radius: 50%;
  background: conic-gradient(
    #0d9488 0% 93.42%,
    #2563eb 93.42% 93.63%,
    #e9a53b 93.63% 94.15%,
    #d8e0e9 94.15% 100%
  );
}

.pcc-donut > div {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 115px;
  height: 115px;
  background: white;
  border-radius: 50%;
}

.pcc-donut strong {
  font-size: 25px;
  font-weight: 850;
}

.pcc-donut small {
  color: #798ba1;
  font-size: 10px;
}

.pcc-legend {
  flex: 1;
  min-width: 150px;
}

.pcc-legend > div {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 0;
  color: #61758c;
  font-size: 11px;
}

.pcc-legend b {
  margin-inline-start: auto;
  color: #203954;
  font-variant-numeric: tabular-nums;
}

.pcc-dot {
  display: inline-block;
  width: 9px;
  height: 9px;
  border-radius: 50%;
}

.pcc-dot.teal {background:#0d9488}
.pcc-dot.blue {background:#2563eb}
.pcc-dot.amber {background:#e9a53b}
.pcc-dot.gray {background:#d8e0e9}

/* ====================================================
   HORIZONTAL BAR CHARTS
   ==================================================== */

.pcc-bars {
  display: flex;
  flex-direction: column;
  gap: 15px;
}

.pcc-bars > div {
  display: grid;
  grid-template-columns: minmax(90px,1.25fr) 2fr 50px;
  align-items: center;
  gap: 10px;
  font-size: 11px;
}

.pcc-bars span {
  color: #61758c;
  overflow-wrap: anywhere;
}

.pcc-bars em {
  display: block;
  height: 12px;
  background: #eaf0f7;
  border-radius: 20px;
  overflow: hidden;
  font-style: normal;
}

.pcc-bars em i {
  display: block;
  height: 100%;
  background: linear-gradient(90deg,#2875d4,#0e9caa);
  border-radius: 20px;
}

.pcc-bars b {
  color: #263e5a;
  font-variant-numeric: tabular-nums;
  text-align: end;
}

/* ====================================================
   ILLUSTRATIVE VERTICAL CHART
   ==================================================== */

.pcc-chart {
  height: 200px;
  padding: 12px 10px 0;
  background: repeating-linear-gradient(
    to top,
    #edf1f7 0,
    #edf1f7 1px,
    transparent 1px,
    transparent 44px
  );
}

.pcc-chart-bars {
  height: 158px;
  display: flex;
  align-items: flex-end;
  justify-content: space-around;
  gap: 10px;
}

.pcc-chart-bars i {
  display: block;
  flex: 1;
  max-width: 36px;
  background: linear-gradient(#3b82f6,#1d9eab);
  border-radius: 5px 5px 0 0;
}

.pcc-chart-labels {
  display: flex;
  justify-content: space-around;
  gap: 8px;
  color: #8393a6;
  font-size: 9px;
  margin-top: 8px;
}

/* ====================================================
   TABLES
   ==================================================== */

.pcc-tablewrap {
  width: 100%;
  overflow-x: auto;
}

.pcc-tablewrap table {
  width: 100%;
  min-width: 660px;
  border-collapse: collapse;
  background: #fff;
  font-size: 11px;
  text-align: start;
}

.pcc-tablewrap th {
  padding: 12px;
  text-align: start;
  background: #f2f6fb;
  border-bottom: 1px solid var(--border);
  color: #65768c;
  font-weight: 800;
  white-space: nowrap;
}

.pcc-tablewrap td {
  padding: 13px 12px;
  border-bottom: 1px solid #edf1f6;
  color: #465c76;
  vertical-align: middle;
}

.pcc-tablewrap tbody tr:hover td {
  background: #f9fbfe;
}

.pcc-tablewrap a {
  color: #2061b8;
  font-weight: 750;
  text-decoration: none;
  white-space: nowrap;
}

.pcc-tablewrap .pcc-empty {
  padding: 32px 12px;
  text-align: center;
  color: #8394a7;
  background: #fafcff;
}

.pcc-status {
  display: inline-block;
  padding: 4px 8px;
  border-radius: 20px;
  background: #edf1f6;
  color: #687990;
  font-size: 10px;
  font-weight: 750;
  white-space: nowrap;
}

.pcc-status.good {
  background: #e2f7ee;
  color: #087a56;
}

.pcc-status.warn {
  background: #fff2d7;
  color: #99650e;
}

.pcc-status.bad {
  background: #ffe9ed;
  color: #b53648;
}

/* ====================================================
   PROGRESS AND COST ANALYSIS
   ==================================================== */

.pcc-progress-number {
  color: #0d9488;
  font-size: 36px;
  font-weight: 850;
  margin: 10px 0 16px;
}

.pcc-progress {
  height: 14px;
  border-radius: 15px;
  overflow: hidden;
  background: #e8eef4;
}

.pcc-progress i {
  display: block;
  height: 100%;
  background: linear-gradient(90deg,#0d9488,#30b6a6);
  border-radius: 15px;
}

.pcc-rows > div {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 12px 0;
  border-bottom: 1px solid #edf1f6;
  font-size: 11px;
}

.pcc-rows > div:last-child {
  border-bottom: 0;
}

.pcc-rows > div > span:first-child {
  color: #5e7289;
}

.pcc-rows b {
  font-variant-numeric: tabular-nums;
}

.pcc-rows a {
  color: #2061b8;
  font-weight: 750;
  text-decoration: none;
}

.pcc-costbar {
  display: flex;
  width: 100%;
  height: 95px;
  overflow: hidden;
  border-radius: 9px;
}

.pcc-costbar span {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 6px;
  color: #fff;
  font-size: 11px;
  font-weight: 750;
  text-align: center;
}

.pcc-costbar span:nth-child(1) {
  flex: 5;
  background: #3074d4;
}

.pcc-costbar span:nth-child(2) {
  flex: 3;
  background: #159b9a;
}

.pcc-costbar span:nth-child(3) {
  flex: 2;
  background: #8667ce;
}

/* ====================================================
   JOB WORKFLOW
   ==================================================== */

.pcc-workflow {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 13px;
}

.pcc-workflow > div {
  display: flex;
  flex-direction: column;
  gap: 7px;
  padding: 16px;
  border: 1px solid #e6edf5;
  border-radius: 9px;
  background: #f6f9fd;
}

.pcc-workflow > div b {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 32px;
  height: 32px;
  border-radius: 9px;
  color: #2462ac;
  background: #e2edfc;
  font-size: 11px;
}

.pcc-workflow strong {
  font-size: 12px;
  color: #263e5b;
}

.pcc-workflow small {
  color: #8392a5;
  font-size: 10px;
}

/* ====================================================
   PRODUCTION ACTIVITIES
   ==================================================== */

.pcc-activity {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.pcc-activity span {
  background: #eff5ff;
  border: 1px solid #d9e8fa;
  border-radius: 7px;
  padding: 8px 12px;
  font-size: 11px;
  font-weight: 700;
  color: #316ba6;
}

/* ====================================================
   TIMELINE
   ==================================================== */

.pcc-timeline > div {
  display: grid;
  grid-template-columns: 75px 12px 1fr;
  gap: 15px;
  align-items: start;
  min-height: 80px;
}

.pcc-timeline > div > span {
  text-align: end;
  font-size: 11px;
  color: #71819a;
  font-weight: 700;
}

.pcc-timeline > div > i {
  position: relative;
  height: 100%;
  border-left: 2px solid #d7e5f5;
}

.pcc-timeline > div > i::before {
  content: "";
  position: absolute;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #3179d9;
  left: -6px;
  top: 2px;
}

.pcc-timeline section b {
  font-size: 12px;
  color: #263d59;
}

.pcc-timeline section p {
  color: #78899d;
  font-size: 11px;
  margin: 4px 0;
}

#pcc-ar:checked ~ .pcc-shell .pcc-timeline > div > i {
  border-left: 0;
  border-right: 2px solid #d7e5f5;
}

#pcc-ar:checked ~ .pcc-shell .pcc-timeline > div > i::before {
  left: auto;
  right: -6px;
}

/* ====================================================
   FOOTER
   ==================================================== */

.pcc-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  flex-wrap: wrap;
  padding: 15px 20px;
  background: #fff;
  border-top: 1px solid var(--border);
  color: #8493a6;
  font-size: 10px;
}

/* ====================================================
   RESPONSIVE DESIGN
   ==================================================== */

@media (max-width: 1150px) {
  .pcc-filterbar {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }

  .pcc-filter-info {
    grid-column: span 2;
  }

  .pcc-kpis {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }
}

@media (max-width: 750px) {
  .pcc-header {
    padding: 19px;
    align-items: flex-start;
    flex-direction: column;
  }

  .pcc-head-actions {
    align-items: flex-start;
  }

  .pcc-header h2 {
    font-size: 21px;
  }

  .pcc-main {
    padding: 12px;
  }

  .pcc-grid2 {
    grid-template-columns: 1fr;
  }

  .pcc-panel {
    padding: 14px;
  }

  .pcc-workflow {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }

  .pcc-nav label {
    flex: 1 1 auto;
    text-align: center;
  }
}

@media (max-width: 430px) {
  .pcc-filterbar {
    grid-template-columns: 1fr;
    padding: 12px;
  }

  .pcc-filter-info {
    grid-column: auto;
  }

  .pcc-kpis {
    gap: 9px;
  }

  .pcc-kpi summary {
    padding: 12px;
    min-height: 145px;
  }

  .pcc-kpi strong {
    font-size: 22px;
  }

  .pcc-kpi .pcc-warning-value {
    font-size: 16px;
  }

  .pcc-kpi-label {
    font-size: 10px;
  }

  .pcc-donut {
    flex-basis: 145px;
    width: 145px;
    height: 145px;
  }

  .pcc-donut > div {
    width: 100px;
    height: 100px;
  }

  .pcc-workflow {
    gap: 8px;
  }
}

/* LIVE ERP INTEGRATION */

.pcc .pcc-live-container {
  margin-top: 18px;
}

.pcc .pcc-live-panel {
  border-color: #cbdff5;
}

.pcc .pcc-live-empty {
  padding: 25px 15px;
  background: #f8fafc;
  color: #8191a5;
  text-align: center;
  border: 1px dashed #d8e2ee;
  border-radius: 8px;
}

.pcc .pcc-live-status {
  margin: 0 0 18px;
  padding: 10px 14px;
  background: #e6f7ef;
  border: 1px solid #c6ead8;
  border-radius: 8px;
  color: #176d4f;
  font-size: 11px;
}

.pcc .pcc-refresh {
  padding: 9px 14px;
  border: 1px solid #cbdff5;
  border-radius: 8px;
  background: #fff;
  color: #174d91;
  font-size: 12px;
  font-weight: 750;
  cursor: pointer;
}

.pcc .pcc-refresh:disabled {
  opacity: .55;
  cursor: wait;
}

.pcc .pcc-live-panel .pcc-tablewrap {
  max-height: 470px;
  overflow: auto;
}

.pcc .pcc-live-panel th {
  position: sticky;
  top: 0;
  z-index: 1;
}

.pcc .pcc-live-panel td a {
  color: #1e62b9;
  text-decoration: none;
  font-weight: 700;
}

/* DM PRODUCTION - LIVE FILTERS AND REFRESH */

/* Hide original audit cards/charts once JS starts,
   preserving tab headings and live panels. */
.pcc.pcc-live-mode .pcc-page >
  :not(.pcc-section-head):not(.pcc-live-container) {
  display: none !important;
}

.pcc .pcc-live-container {
  margin-top: 14px;
}

.pcc .pcc-live-metrics {
  display: grid;
  grid-template-columns: repeat(4,minmax(0,1fr));
  gap: 13px;
  margin-bottom: 18px;
}

.pcc .pcc-live-metric {
  min-width: 0;
  background: white;
  border: 1px solid #e3e9f2;
  border-radius: 11px;
  padding: 17px;
  box-shadow: 0 2px 8px rgba(25,50,80,.04);
}

.pcc .pcc-live-metric-label {
  font-size: 11px;
  font-weight: 700;
  color: #65758c;
}

.pcc .pcc-live-metric strong {
  display: block;
  font-size: 25px;
  font-weight: 850;
  color: #1b3556;
  margin: 8px 0 5px;
  font-variant-numeric: tabular-nums;
  overflow-wrap: anywhere;
}

.pcc .pcc-live-metric small {
  display: block;
  color: #8493a6;
  font-size: 10px;
}

.pcc .pcc-refresh-live {
  border: 1px solid #d4e3f4;
  border-radius: 8px;
  padding: 9px 14px;
  background: white;
  color: #1b528e;
  cursor: pointer;
  font-size: 12px;
  font-weight: 750;
}

.pcc .pcc-refresh-live:disabled {
  opacity: .55;
  cursor: wait;
}

.pcc .pcc-current-status {
  padding: 10px 17px;
  font-size: 11px;
  border-bottom: 1px solid #dce6f2;
  background: #eaf3ff;
  color: #3c6089;
}

.pcc .pcc-current-status.success {
  background: #e7f7ed;
  border-color: #c7e8d5;
  color: #176a4b;
}

.pcc .pcc-current-status.warning {
  background: #fff4dd;
  border-color: #f1dfae;
  color: #87600d;
}

.pcc .pcc-current-status.error {
  background: #ffe9ec;
  color: #ae3447;
}

.pcc .pcc-live-warning {
  border: 1px solid #f0d8aa;
  border-radius: 8px;
  background: #fff7e7;
  color: #8f651d;
  padding: 11px 13px;
  margin-bottom: 14px;
  font-size: 11px;
}

.pcc .pcc-live-empty {
  background: #f9fbfe;
  border: 1px dashed #dce5f0;
  border-radius: 8px;
  text-align: center;
  padding: 26px 15px;
  color: #8191a5;
  font-size: 12px;
}

.pcc .pcc-live-bar {
  display: grid;
  grid-template-columns: minmax(85px,1fr) 2fr 45px;
  align-items: center;
  gap: 10px;
  padding: 7px 0;
  font-size: 11px;
}

.pcc .pcc-live-bar span {
  color: #65778e;
  overflow-wrap: anywhere;
}

.pcc .pcc-live-bar > div {
  height: 12px;
  background: #edf2f8;
  border-radius: 20px;
  overflow: hidden;
}

.pcc .pcc-live-bar i {
  display: block;
  height: 100%;
  border-radius: 20px;
  background: linear-gradient(90deg,#2875d4,#0e9caa);
}

.pcc .pcc-live-bar b {
  text-align: end;
  font-variant-numeric: tabular-nums;
}

.pcc .pcc-live-container .pcc-tablewrap {
  max-height: 480px;
  overflow: auto;
}

.pcc .pcc-live-container th {
  position: sticky;
  top: 0;
  z-index: 1;
}

@media(max-width:1000px) {
  .pcc .pcc-live-metrics {
    grid-template-columns: repeat(2,minmax(0,1fr));
  }
}

@media(max-width:450px) {
  .pcc .pcc-live-metric {
    padding: 12px;
  }

  .pcc .pcc-live-metric strong {
    font-size: 21px;
  }

  .pcc .pcc-live-metric-label {
    font-size: 10px;
  }

  .pcc .pcc-live-bar {
    grid-template-columns: 80px 1fr 35px;
    gap: 6px;
  }
}
